import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1192, own='cte_115.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 818 Precision Metal Manufacturing II ----
H("818.d.1.A",3,"A second-year machining student compares the degrees, apprenticeships and NIMS credentials that lead to a CNC programmer job and notes the algebra and geometry she still needs. She is determining:","academic knowledge and skills required for postsecondary education and careers",["only her weekend plans","only her lunch choices","only the shop's color"],"Know the requirements before choosing a path.")
H("818.d.1.A",4,"A student planning a career in CNC programming should take courses in:","math, drafting and computer applications",["only choir","only cooking","only art history"],"CNC careers rely on these skills.")
H("818.d.1.B",3,"A shop owner explains that customers expect on-time delivery, parts to print and quick answers when a problem arises. Meeting these expectations helps to:","foster positive customer satisfaction",["lose repeat customers","reduce orders","raise complaints"],"Employer expectations support customer satisfaction.")
H("818.d.1.B",4,"A machinist who finds that a batch will be late should:","tell the supervisor right away so the customer can be notified",["hide the delay","blame the customer","ship it without notice"],"Early communication preserves trust.")
H("818.d.1.C",3,"A student practices a mock job interview, completes an application and writes a resume listing her NIMS credentials. She is demonstrating standards required in the workplace such as:","interviewing, completing applications and resume writing",["only texting","only gaming","only sleeping"],"Hiring steps follow standards.")
H("818.d.1.C",4,"A good resume for a machinist apprenticeship should list:","skills, training and relevant projects or credentials",["only favorite shows","only her age","only her nickname"],"A resume shows qualifications.")
H("818.d.1.D",3,"Each semester a student checks which NIMS credentials she has earned against the list she set in ninth grade and updates her plan. She is evaluating:","progress toward personal career goals",["a menu","a score","a dance"],"Review progress against goals.")
H("818.d.1.D",4,"Reviewing progress toward a career goal helps a student:","adjust the plan and stay on track",["avoid planning","skip steps","forget the goal"],"Progress checks guide corrections.")
H("818.d.1.E",3,"A machinist confirms the revision letter on a print with the engineer by email before cutting a batch. She is communicating to:","clarify objectives and expectations in the workplace",["slow the batch down","avoid work","confuse the engineer"],"Confirm requirements before production.")
H("818.d.1.E",4,"When a print revision is unclear, the machinist should:","ask the engineer or supervisor before cutting",["guess which is right","use the older print","skip the part"],"Ask before cutting.")
H("818.d.1.F",3,"A CNC shop posts its lockout/tagout procedure, requires hearing protection near the loud saws and keeps safety data sheets handy. These show skills related to:","health and safety in the workplace as specified by OSHA",["office decorating","company logos","shift bidding"],"OSHA rules protect workers.")
H("818.d.1.F",4,"A technician is about to clear a jam inside a CNC cell. To keep anyone from restarting the equipment while her hands are inside, she should:","apply her own lock and tag to the energy source",["ask a coworker to watch the start button","turn the lights off","slow the feed rate"],"Personal lockout/tagout controls hazardous energy.")
H("818.d.2.A",3,"A machinist uses tables in the handbook to find the tap drill for a 5/16-18 thread and the allowance for a class 2 fit. She is applying:","technical aspects found in The Machinery's Handbook",["a recipe book","a sports almanac","a dictionary of slang"],"The handbook provides threads and fits data.")
H("818.d.2.A",4,"A machinist needs the minor diameter of a standard thread. The best source is:","The Machinery's Handbook",["a cookbook","a novel","a magazine"],"Thread data is in the handbook.")
H("818.d.2.B",3,"A student searches a tooling supplier's website for insert recommendations and checks the source is a reputable manufacturer. She is selecting:","appropriate Internet resources as applied to manufacturing",["random pages","unknown ads","only social media"],"Use reliable resources.")
H("818.d.2.B",4,"A reliable Internet source for the cutting speed of a particular insert grade is:","the insert manufacturer's technical page",["an anonymous comment","a game forum","an unrelated blog"],"Manufacturer data is most reliable.")
H("818.d.3.A",3,"A student programs and turns a multi-diameter shaft with a groove and a thread to NIMS Level 1 print dimensions. She is developing:","a detailed turning part such as the NIMS Level 1 turning project",["a poster","a sculpture","a recipe"],"NIMS turning project practice.")
H("818.d.3.A",4,"The NIMS credential is useful to a machinist because it:","proves skills against an industry standard",["replaces work","hides skills","reduces pay"],"Industry-recognized credential.")
H("818.d.3.B",3,"A student mills a plate with a pocket, a bolt-hole pattern and a contour to NIMS Level 1 print dimensions and inspects each feature. She is developing:","a detailed milling part such as the NIMS Level 1 milling part",["a poem","a quilt","a poster"],"NIMS milling project practice.")
H("818.d.3.B",4,"A NIMS-style milling project is graded mainly on:","how closely the part matches the print tolerances",["how fast it cools","how it looks in a photo","the student's nickname"],"Accuracy to print matters.")
H("818.d.4.A",3,"A student researches how punched tape and early servo controls led to modern computer-controlled machines. She is researching:","the history of numerical control machines",["the history of cooking","the history of dance","the history of painting"],"NC history leads to CNC.")
H("818.d.4.A",4,"Early numerical control machines were commonly programmed using:","punched tape",["touch screens","voice commands","the cloud"],"Tape preceded computers.")
H("818.d.4.B",3,"A class tours a plant and sees a 2-axis lathe, a 3-axis vertical mill, a wire EDM and a laser cutter all running programs. They are distinguishing among:","different types of CNC machines used in industry",["kinds of pottery","types of fruit","sports teams"],"CNC includes many machine types.")
H("818.d.4.B",4,"A wire EDM machine is used to:","cut hard metals using electrical sparks and a wire",["print paper","bake dough","dye fabric"],"EDM erodes metal electrically.")
H("818.d.4.C",3,"A new CNC operator learns to keep the door closed while running, to know where the emergency stop is and to never reach into a moving machine. She is demonstrating:","safety rules for CNC operation",["shortcuts","guesses","games"],"CNC safety rules protect operators.")
H("818.d.4.C",4,"If something unexpected happens on a running CNC machine, the operator should first:","press the emergency stop",["reach in to fix it","open the door and watch","turn up the feed"],"E-stop halts motion.")
H("818.d.4.D",3,"A student types a program at the control, loads another from a USB drive and receives a third through a network from the CAM station. She is demonstrating:","the methods by which programs can be entered into a control",["methods of watering plants","methods of sharpening pencils","methods of folding paper"],"Programs can be entered several ways.")
H("818.d.4.D",4,"One way to enter a CNC program at the machine is:","manual data input (MDI)",["mailing a letter","painting the control","knocking on the door"],"MDI types commands at the control.")
H("818.d.4.E",3,"A student labels a drawing with the terms spindle, turret, work offset, feed rate and G-code to build her shop vocabulary. She is using:","appropriate machining terminology to enhance CNC vocabulary",["slang from games","random words","only nicknames"],"Correct terms prevent mistakes.")
H("818.d.4.E",4,"The rate at which the cutter or workpiece advances during cutting is the:","feed rate",["spindle speed","tool offset","work zero"],"Feed rate = travel per time or per revolution.")
H("818.d.5.A",3,"A student studies the servo motors and ball screws that move the axes of a CNC mill and how the stepper motors on a small router differ. She is examining:","the types of drive motors used on CNC machinery",["kinds of kitchen mixers","types of fans","sets of speakers"],"Servo and stepper drives move axes.")
H("818.d.5.A",4,"Compared with stepper motors, servo motors on a CNC machine typically provide:","feedback for closed-loop position control",["no feedback","lower precision","less torque control"],"Servos use encoders.")
H("818.d.5.B",3,"A student explains that every point on a flat part can be located by an X distance and a Y distance from the origin and shows it on a graph. She is explaining:","the Cartesian coordinate system",["the metric system","the time zone system","the solar system"],"Cartesian coordinates use axes from an origin.")
H("818.d.5.B",4,"On a CNC mill, the point at coordinates X2, Y3 lies:","2 units along X and 3 units along Y from the origin",["3 units along X and 2 along Y","2 units below the origin","at the origin"],"X first, then Y.")
H("818.d.5.C",3,"A programmer compares one program that moves to X1.0, X2.5, X4.0 from the origin and another that moves 1.0, 1.5, 1.5 from each last position. She is differentiating between:","absolute and incremental positioning",["hot and cold","fast and slow","big and small"],"Absolute vs incremental.")
H("818.d.5.C",4,"In incremental positioning, each move is measured from:","the tool's current position",["the program start only","the part's end only","the machine's home only"],"Incremental uses the last position.")
H("818.d.5.D",3,"On a print, one drawing gives every dimension from a single edge and another gives each dimension from the previous feature. The student is illustrating the difference between:","datum and delta dimensioning",["color and shade","price and cost","front and back"],"Datum vs delta (chain) dimensioning.")
H("818.d.5.D",4,"A benefit of datum dimensioning is that:","errors do not stack from one feature to the next",["it uses more paper","it adds errors","it is harder to read"],"Each feature is located from the same datum.")
H("818.d.6.A",3,"A student writes out which tools, speeds, feeds and cutting order she will use to machine an aluminum bracket and then labels each operation. She is developing:","a detailed process plan including tool selection, feeds and speeds",["a vacation plan","a budget plan","a party plan"],"A process plan guides CNC programming.")
H("818.d.6.A",4,"A detailed CNC process plan should be completed:","before writing the program",["after machining","after shipping","after inspection"],"Plan first, then program.")
H("818.d.6.B",3,"A student arranges the operations so that roughing comes before finishing and plans in-process checks of the critical bore. She is developing:","a logical sequence of operations and appropriate inspection points",["a random list","an alphabetical list","a color chart"],"Sequence and inspection planning.")
H("818.d.6.B",4,"Roughing cuts are usually done before finishing cuts because:","they remove most material and leave stock for the final pass",["they use less power","they are quieter","they take no time"],"Rough then finish.")
H("818.d.6.C",3,"A student mounts a triangular carbide insert on a holder, tightens the screw and runs a turning pass. She is demonstrating the use of:","carbide inserts",["wooden blades","paper tips","rubber tips"],"Carbide inserts are common cutting tools.")
H("818.d.6.C",4,"A key advantage of carbide inserts is that they:","stay hard at high cutting speeds",["melt easily","dull instantly","cost nothing"],"Carbide resists heat.")
H("818.d.6.D",3,"A machinist chooses an insert's shape, grade, nose radius and coating after checking the catalog for the material to be cut. She is applying:","carbide inserts by determining the correct type, grade and geometry",["random inserts","only the cheapest","no insert"],"Match the insert to the job.")
H("818.d.6.D",4,"A larger nose radius on a turning insert generally gives:","a stronger tip but more cutting pressure",["a weaker tip","no change","no cutting"],"Larger radius = stronger, more pressure.")
H("818.d.7.A",3,"A student swaps from a drill to a 1/2-inch end mill to a face mill by hand and by using the machine's automatic changer. She is performing:","various types of tool changes",["wardrobe changes","station changes","channel changes"],"Tool changes are manual or automatic.")
H("818.d.7.A",4,"Before changing a tool manually on a CNC mill, the operator should first:","stop the spindle and make sure the machine is in a safe state",["reach in while it spins","open the guard during a cut","remove the tool during cutting"],"Safe state first.")
H("818.d.7.B",3,"A class installs collet-style tool holders that can be exchanged in the spindle in seconds without re-measuring each tool. They are demonstrating:","quick change tooling used on CNC milling machines",["slow tooling","hand-cranked tooling","glued tooling"],"Quick-change tooling saves time.")
H("818.d.7.B",4,"Quick-change tooling reduces:","setup time",["spindle speed","part size","machine height"],"It speeds tool swaps.")
H("818.d.7.C",3,"After use, a student wipes each tool holder and returns it to its labeled slot on a rack so cutters are not chipped and are easy to find. She is demonstrating:","appropriate tool storage",["careless handling","random storage","leaving tools on the table"],"Good storage protects tools.")
H("818.d.7.C",4,"Cutting tools are stored in racks or drawers so that cutting edges:","are protected from damage",["are exposed","knock together","get dirty"],"Protected edges stay sharp.")
H("818.d.7.D",3,"A student enters the length of a 3/8-inch end mill into the tool-offset table so the control knows where its tip is relative to the part. She is demonstrating the use of:","tool offset registers",["random numbers","paint colors","clock settings"],"Offset registers store tool data.")
H("818.d.7.D",4,"A tool length offset tells the control:","how far the tool tip extends from the spindle",["the part's color","the shop's address","the time of day"],"Offsets give tool geometry.")
H("818.d.7.E",3,"A student touches off a tool on the part's surface and records the Z value to find that tool's length offset. She is determining:","tool offset length",["a quilt length","a recipe amount","a travel distance"],"Touch-off measures length offset.")
H("818.d.7.E",4,"To measure a tool's length offset, an operator commonly:","touches the tool to a known surface and records the Z position",["measures the tool's color","weighs the tool","paints the tool"],"Touch-off or presetter.")
H("818.d.7.F",3,"A student enters work and tool offsets for each of three tools and runs a first part to confirm the dimensions. She is incorporating:","tool offsets for a setup",["colors for a quilt","songs for a playlist","dates for a calendar"],"Offsets are part of setup.")
H("818.d.7.F",4,"After entering offsets for a new setup, the operator should:","run the first part carefully and verify its dimensions",["run at full speed unwatched","skip inspection","leave without checking"],"Prove out the setup.")

H("818.d.8.A",3,"Before running a CNC lathe, a student closes the chuck guard, checks that the jaws are tight on the bar and keeps the door interlock working. She is using:","equipment commonly associated with a CNC lathe in a safe manner",["equipment carelessly","equipment without guards","equipment with the door open"],"CNC lathe safety.")
H("818.d.8.A",4,"The chuck pressure on a CNC lathe is checked so that the workpiece:","does not come loose at spindle speed",["runs hotter","turns slower","looks better"],"Insufficient grip is a hazard.")
H("818.d.8.B",3,"A student points to the spindle, chuck, turret, tailstock and operator panel on a CNC lathe and explains what each does. She is recognizing, naming and describing:","the primary components of a CNC lathe",["parts of a bicycle","parts of a loom","parts of a guitar"],"Know lathe components.")
H("818.d.8.B",4,"On a CNC lathe, the turret is the component that:","holds several tools and indexes the right one into position",["holds the chips","cools the spindle","displays the program"],"Turrets carry tools.")
H("818.d.8.C",3,"At the start of each shift a student checks the way lube level, the hydraulic pressure and the air pressure on the CNC lathe. She is performing:","preventative maintenance checks on a CNC lathe",["a shop tour","a paint job","a lunch order"],"PM checks prevent downtime.")
H("818.d.8.C",4,"Checking the way lube on a CNC lathe each day helps to:","prevent wear and keep the slides moving smoothly",["raise noise","slow the spindle","hide leaks"],"Lubrication reduces wear.")
H("818.d.8.D",3,"A student uses a refractometer to check the coolant mix on the lathe and adds concentrate when the reading is low. She is testing:","the coolant for proper density and adjusting it",["the soda for flavor","the tea for sweetness","the paint for color"],"Coolant concentration matters.")
H("818.d.8.D",4,"A tool used to measure the concentration of water-soluble coolant is a:","refractometer",["micrometer","plumb bob","level"],"Refractometers read concentration.")
H("818.d.8.E",3,"The operator turns on the main disconnect, presses the power button and waits for the control to boot before homing the axes. She is performing:","a power up on a standard CNC lathe",["a shutdown","a restart of a laptop only","a lunch break"],"Power-up sequence.")
H("818.d.8.E",4,"After a CNC lathe is powered on, the operator typically needs to:","home the axes before running a program",["load the coolant","disable the stop","remove the guards"],"Homing sets a reference.")
H("818.d.8.F",3,"A student uses the handwheel and jog keys to move the turret toward the part in small steps until it nearly touches the stock. She is demonstrating:","the use of jog controls on the operator panel of a CNC lathe",["a dance","a drawing","a puzzle"],"Jog controls move axes manually.")
H("818.d.8.F",4,"When jogging a tool close to a part, the operator should use:","a slow jog speed or small handwheel increments",["maximum rapid","no guard","closed eyes"],"Slow near the work.")
H("818.d.8.G",3,"A student assembles a boring bar in its holder, sets the stickout and measures it on a presetter before loading it into the turret. She is demonstrating the ability to:","locate, assemble and measure tooling for a CNC lathe",["throw tools","hide tools","paint tools"],"Tool preparation.")
H("818.d.8.G",4,"The stickout of a boring bar is kept short because a long overhang:","can cause chatter and poor accuracy",["makes it cool","makes it quiet","increases rigidity"],"Overhang reduces stiffness.")
H("818.d.8.H",3,"A student loads each turned-part tool into its numbered turret pocket to match the tool list in the program. She is:","installing tools and holders in the automatic tool changer locations of a CNC lathe",["painting the turret","oiling the chuck","cleaning the floor"],"Tool numbers must match the program.")
H("818.d.8.H",4,"If a tool is placed in the wrong turret position, the machine may:","use the wrong tool and crash",["run quieter","run cooler","skip the program"],"Tool position must match.")
H("818.d.8.I",3,"A student touches the tool to the face of the bar stock and sets that Z position as the part's face zero on the lathe. She is:","locating and setting the workpiece to zero on a CNC lathe",["setting a clock","setting a table","setting a timer"],"Z zero is commonly the part face.")
H("818.d.8.I",4,"On many CNC lathe programs, the Z zero is set at:","the finished face of the part",["the tailstock","the ceiling","the chip pan"],"Face zero is common.")
H("818.d.8.J",3,"After touching off, the student enters the work offset in G54 so the program references the part instead of the machine origin. She is setting:","work offsets for the part to be machined",["wall offsets","rent offsets","pay offsets"],"Work offsets locate the part.")
H("818.d.8.J",4,"A work offset such as G54 tells the control:","where the part's zero is relative to the machine",["when to stop for lunch","what color the part is","how many workers are present"],"G54 stores part zero.")
H("818.d.8.K",3,"For each turning, boring and threading tool in the turret, the student enters the X and Z geometry values that the control uses to place the tool tip. She is setting:","the proper geometry/tool offsets for each tool in a standard tool turret",["a recipe","a poem","a quilt"],"Geometry offsets are per tool.")
H("818.d.8.K",4,"If a tool's offset is entered incorrectly, the finished part will most likely:","have the wrong size or the tool may crash",["be painted","be lighter","be quieter"],"Wrong offset = wrong dimension.")
H("818.d.8.L",3,"After proving out the program in single-block mode, the operator presses cycle start and lets the lathe run through all the operations by itself. She is operating:","a CNC lathe in automatic mode",["a toaster","a printer","a tablet"],"Automatic mode runs the program.")
H("818.d.8.L",4,"While a CNC lathe runs in automatic mode, the operator should:","stay at the machine and watch for problems",["leave for the day","open the door","remove the guard"],"Monitor the cycle.")
H("818.d.8.M",3,"At the end of the shift, the student retracts the turret, cleans the chips, presses the power-off button and flips the main disconnect. She is illustrating:","the proper power down process on a CNC lathe",["the power up","a restart","a resume"],"Shutdown sequence.")
H("818.d.8.M",4,"Before powering down a CNC lathe, the operator should first:","return the axes to a safe position and clean the machine",["unplug it mid-cut","cut the main power at once","leave chips in place"],"Park and clean.")
H("818.d.9.A",3,"A student checks that the vise is tight, the spindle is stopped and the enclosure door is closed before pressing cycle start on a CNC mill. She is using:","equipment commonly found on and around a CNC mill in a safe manner",["equipment carelessly","equipment with the door open","equipment without goggles"],"CNC mill safety.")
H("818.d.9.A",4,"Before starting a CNC mill program, the operator should confirm that the:","workholding is secure and the area is clear",["door is open","vise is loose","tools are missing"],"Secure before starting.")
H("818.d.9.B",3,"A student points to the column, table, spindle, tool changer and control on a vertical machining center and explains each. She is recognizing, naming and describing:","the primary components of a CNC mill",["parts of a bicycle","parts of a stove","parts of a phone"],"Mill components.")
H("818.d.9.B",4,"On a CNC mill, the automatic tool changer is the component that:","swaps tools in and out of the spindle during a program",["cools the part","holds paper","clears chips only"],"ATCs swap tools automatically.")
H("818.d.9.C",3,"Before a mill job, an operator checks the oil in the way lubrication reservoir, the air pressure and the spindle taper for chips. She is performing:","preventative maintenance checks on a CNC mill",["a paint check","a menu check","a grade check"],"PM keeps machines accurate.")
H("818.d.9.C",4,"Keeping the spindle taper clean on a CNC mill helps to:","hold the tool holder accurately",["add noise","speed rust","reduce power"],"A clean taper seats tools.")
H("818.d.9.D",3,"A student dips a test strip into the coolant tank on a CNC mill to read its pH and concentration and adjusts the mix. She is testing:","the coolant for proper density and adjusting it",["the milk for taste","the juice for sugar","the water for chlorine"],"Coolant concentration affects tool life.")
H("818.d.9.D",4,"Coolant that is too weak in concentration can cause:","rust and shorter tool life",["better finish","longer tool life","less rust"],"Weak coolant fails to protect.")
H("818.d.9.E",3,"An operator switches on the main power to the mill, waits for the screen to load and then clears the alarms before homing the machine. She is performing:","a power up on a standard CNC mill",["a shutdown","a reboot of a phone","a break"],"CNC mill power-up.")
H("818.d.9.E",4,"The homing routine on a CNC mill is run to:","establish the machine's reference position",["speed up the spindle","change tools","clean the chips"],"Homing sets machine zero.")
H("818.d.9.F",3,"A student uses the jog dial on the pendant to move the table in X and Y until the cutter sits just above the corner of the part. She is demonstrating:","the use of jog controls on a CNC mill",["a video game","a map reading","a board game"],"Jog controls position axes.")
H("818.d.9.F",4,"The Z axis on a vertical mill is the axis that moves:","the spindle up and down",["the table left to right","the table front to back","the vise open"],"Z is vertical.")
H("818.d.9.G",3,"A student assembles an end mill in a collet, sets it to the right stickout and measures its length on a presetter before loading it. She is demonstrating the ability to:","locate, assemble and measure tooling for a CNC mill",["bend tools","paint tools","hide tools"],"Preparing mill tooling.")
H("818.d.9.G",4,"A tool presetter is used to:","measure a tool's length and diameter off the machine",["clean the coolant","paint the tool","cool the spindle"],"Presetters save machine time.")
H("818.d.9.H",3,"A student loads each cutter into its numbered pocket in the tool magazine so each matches the T number in the program. She is:","installing tools and holders in the automatic tool changer locations of a CNC mill",["cleaning the floor","painting the magazine","oiling the vise"],"Match tool numbers.")
H("818.d.9.H",4,"If tool 5 in the program is loaded in pocket 6 of the magazine, the likely result is that:","the wrong tool will be used",["the machine runs faster","the part is shinier","the cycle ends early"],"Mismatch causes errors.")
H("818.d.9.I",3,"A student uses an edge finder to locate the left and front edges of a plate in the vise and sets those as X zero and Y zero. She is:","locating and setting a workpiece to zero on a CNC mill",["setting a clock","setting a table","setting a timer"],"Edge finding sets XY zero.")
H("818.d.9.I",4,"An edge finder helps an operator to:","locate the edge of a part to set zero",["cool the cutter","measure a thread","clean the vise"],"It finds edges.")
H("818.d.9.J",3,"After finding the part edges, the student enters the X, Y and Z values into G54 so the program works from the part's zero. She is setting:","work offsets for the part to be machined",["table offsets","room offsets","pay offsets"],"Work offsets locate the part.")
H("818.d.9.J",4,"Using G55 instead of G54 in a program means the control uses:","a different stored work offset",["a different cutter","a different spindle","a different coolant"],"Work offsets G54–G59.")
H("818.d.9.K",3,"For each end mill, drill and face mill in the magazine, the student enters its length and diameter offsets in the tool table. She is setting:","the proper geometry/tool offsets for each tool in a standard tool-changer",["a quilt","a poem","a recipe"],"Tool offsets per tool.")
H("818.d.9.K",4,"If a mill's tool length offset is too short, the tool will:","stop above the part and cut too shallow",["cut too deep always","cut perfectly","skip the program"],"Offset affects Z depth.")
H("818.d.9.L",3,"After single-block proving, the operator closes the door and presses cycle start to let the mill run the entire program on its own. She is operating:","a CNC mill in automatic mode",["a microwave","a camera","a blender"],"Automatic mode runs the program.")
H("818.d.9.L",4,"While a mill runs a new program in automatic mode, the operator should keep a hand near the:","feed hold or emergency stop",["door latch only","coolant tank","tool rack"],"Be ready to stop.")
H("818.d.9.M",3,"At the end of the day the student parks the table, cleans the chips, powers off the control and then turns off the main disconnect. She is illustrating:","the proper power down process on a CNC mill",["a power up","a restart","a standby"],"Proper shutdown.")
H("818.d.9.M",4,"Before powering down a CNC mill, the operator should:","clean the machine and move the axes to a safe position",["leave chips in place","unplug it mid-cycle","remove the guards"],"Clean and park.")

H("818.d.10.A",3,"A programmer uses the sine and cosine of a 30-degree chamfer to figure out the X and Z end points of a turned taper from the print. She is calculating:","trigonometry to determine coordinates from technical drawings for a CNC lathe",["a recipe","a budget","a schedule"],"Trig finds coordinates not dimensioned.")
H("818.d.10.A",4,"A 45-degree chamfer on a turned shoulder spans a set distance along the Z axis. Its change in X on the radius is:","the same as its Z length",["half of its Z length","twice its Z length","zero"],"At 45 degrees, rise equals run.")
H("818.d.10.B",3,"A programmer shifts the path of a round-nose tool using the tool's nose radius and the cutting angle so the finished surface comes out on size. She is using:","trigonometry for determining cutter offsets",["art techniques","guessing","a coin flip"],"Offsets use trig.")
H("818.d.10.B",4,"Tool nose radius compensation is used on a lathe to:","correct for the rounded tip of the cutting insert",["speed up the spindle","cool the part","clear chips"],"Compensates for the radius.")
H("818.d.10.C",3,"A programmer calculates the spindle speed in RPM from the cutting speed and the part diameter, and the feed per revolution from the chip load. She is using:","appropriate mathematical skills to solve problems while programming a CNC lathe",["no math","guesses","only memory"],"Math supports programming.")
H("818.d.10.C",4,"For a constant surface speed on a lathe, as the diameter gets smaller the RPM must:","increase",["decrease","stay the same","go to zero"],"RPM = CS / diameter.")
H("818.d.10.D",3,"A student writes a short program that faces the end of a bar, then turns a 1-inch diameter for 2 inches at a set feed. She is writing:","a simple program to face and turn",["a poem","a letter","a story"],"Face and turn program.")
H("818.d.10.D",4,"In a lathe program, a facing pass is typically made by moving the tool along:","the X axis toward the centerline",["the Z axis only","the Y axis","the spindle"],"Facing moves in X.")
H("818.d.10.E",3,"A student adds G02 and G03 moves to cut a radius, a taper, a groove and a G76 thread to the end of her turning program. She is writing:","a simple program to cut radiuses, angles, grooves and threads",["a song","a menu","a quote"],"Contour and threading programs.")
H("818.d.10.E",4,"G02 and G03 in a CNC program command:","clockwise and counterclockwise arc moves",["tool changes","spindle stops","coolant on and off"],"Circular interpolation.")
H("818.d.10.F",3,"A programmer activates G41 so the control shifts the tool path to the left by the tool's radius when finishing a contour. She is writing:","a program using cutter radius compensation",["a program without offsets","a paper plan","a cooking recipe"],"CRC shifts the path.")
H("818.d.10.F",4,"Cutter radius compensation lets the programmer:","program the part's profile instead of the tool's center",["ignore the print","skip the tool","use no offsets"],"Program part geometry.")
H("818.d.10.G",3,"Instead of writing every roughing pass by hand, a programmer calls a G71 cycle with a start and end for the contour and a depth of cut. She is writing:","a program using canned cycles such as G71",["a list of random numbers","a shopping list","a mailing"],"Canned cycles shorten programs.")
H("818.d.10.G",4,"A G71 canned cycle on a lathe is used to:","rough out a profile with repeated passes",["change tools","start coolant","stop the spindle"],"G71 is a stock removal cycle.")
H("818.d.10.H",3,"A student writes a full program for a complex NIMS Level 1 turned part with faces, diameters, radiuses and threads and then machines it. She is writing:","a program and producing a complex part such as a NIMS Level 1 CNC turning project",["a doodle","a note","a poster"],"Complete CNC turning project.")
H("818.d.10.H",4,"Before running a new complex program on a lathe, a good practice is to:","simulate it and run it in single-block mode",["run it blind at full speed","skip the simulation","remove the guard"],"Prove out new programs.")
H("818.d.11.A",3,"A programmer uses trigonometry to find the XY coordinates of the holes on a 3-inch bolt circle at 60-degree spacing for a mill program. She is using:","trigonometry to determine coordinates from technical drawings for a CNC mill",["a coin toss","a map","a wish"],"Trig finds hole positions.")
H("818.d.11.A",4,"For holes spaced every 60 degrees around a bolt circle, the number of holes is:","6",["4","5","8"],"360 ÷ 60 = 6.")
H("818.d.11.B",3,"A programmer calculates how far to shift a cutter path along an angled wall so the part ends up the right size on a mill. She is using:","trigonometry for determining cutter offsets on a mill",["art","guessing","a hunch"],"Offsets use trig.")
H("818.d.11.B",4,"The distance a cutter's center must stay from a finished wall equals:","the cutter radius",["the cutter diameter","zero","the part width"],"Center is a radius away.")
H("818.d.11.C",3,"A programmer computes the RPM for a 3/4-inch end mill in aluminum and the feed rate from the chip load and number of flutes. She is using:","appropriate mathematical skills to solve problems while programming a CNC mill",["no math","only guesses","only memory"],"Math supports programming.")
H("818.d.11.C",4,"The feed rate for an end mill is found by multiplying:","RPM by chip load per tooth by number of teeth",["RPM by diameter","depth by width","diameter by length"],"IPM = RPM × chip load × flutes.")
H("818.d.11.D",3,"A student writes a short mill program that spot drills, drills and taps four holes using a drilling cycle. She is writing:","a simple program to perform hole operations",["a quiz","a novel","a letter"],"Hole operations program.")
H("818.d.11.D",4,"A G81 canned cycle on a mill is used for:","drilling a hole in one pass to depth",["tapping only","boring only","facing only"],"G81 is a simple drilling cycle.")
H("818.d.11.E",3,"A student adds arcs and angled lines to her mill program so a corner has a 0.250-inch radius and an edge has a 30-degree bevel. She is writing:","a simple program to cut radiuses and angles",["a poem","a menu","a recipe"],"Contour programs include arcs.")
H("818.d.11.E",4,"A 0.250-inch radius on a corner can be programmed using:","G02 or G03 arc commands",["M08","G54","T1"],"Arc commands cut radii.")
H("818.d.11.F",3,"A programmer uses G41 to compensate for the cutter's radius and enters the cutter in a smooth arc so it enters the cut without a dwell mark. She is writing:","a program using cutter radius compensation and ramping",["a program with no offsets","a paper plan","a cooking recipe"],"CRC and ramping.")
H("818.d.11.F",4,"Ramping into a cut, instead of plunging, helps to:","reduce tool stress and give a smoother entry",["increase tool wear","create more noise","skip a pass"],"Ramping is gentler.")
H("818.d.11.G",3,"A student writes the complete program for a NIMS Level 1 milled part with pockets, hole patterns and a profile and then machines it on a CNC mill. She is writing:","a program and producing a complex part such as a NIMS Level 1 CNC milling project",["a quick poster","a note","a doodle"],"Complete CNC milling project.")
H("818.d.11.G",4,"After a CNC mill finishes a complex part, the student verifies it by:","inspecting the critical features against the print",["looking at it","skipping the print","guessing"],"Inspect to print.")
H("818.d.12.A",3,"A quality engineer reviews a print that uses datums, flatness and position tolerances to see whether a part can be made and inspected. She is evaluating:","engineering drawings using geometric dimensioning and tolerancing",["a restaurant menu","a bus route","a fruit label"],"GD&T evaluation.")
H("818.d.12.A",4,"In GD&T, a datum is:","a reference feature from which measurements are made",["a type of cutter","a machine speed","a coolant type"],"Datums are references.")
H("818.d.12.B",3,"A class reads the ASME Y14.5M standard to learn what each symbol in a feature control frame means. They are discussing:","the American Society of Mechanical Engineers Y14.5M standard",["a cooking guide","a travel brochure","a sports rulebook"],"Y14.5 defines GD&T.")
H("818.d.12.B",4,"The ASME Y14.5 standard is used to:","define how geometric tolerances are shown and interpreted on drawings",["set shop hours","set prices","set menus"],"A common language for tolerances.")
H("818.d.12.C",3,"A student compares the principles of ISO 9001, Six Sigma and lean manufacturing to see how each helps a shop improve product quality. She is appraising:","various quality control and management programs",["only sports","only cooking","only fashion"],"Quality programs improve consistency.")
H("818.d.12.C",4,"A quality program such as Six Sigma is mainly aimed at:","reducing defects and variation in processes",["raising prices","hiding errors","slowing work"],"Six Sigma reduces variation.")

